package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// avoid unused import error
var _ = decimal.New

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLabel string = strings.Repeat(" ", 20) // PIC X(20) len=20 = SPACES
var WsACount int64 = 0 // PIC 99 len=2 = 0
var WsTotalA int64 = 0 // PIC 999 len=3 = 0
var WsCount int64 = 0  // PIC 999 len=3 = 0

var PartRecGlobal PartRec

// file handling
var partFileLines []string
var partFileIndex int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatPic9(v int64, digits int) string {
	// keep low-order digits, zero padded
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// handle negative? keep low-order digits
	// For non-negative simple mod
	if v < 0 {
		// COBOL low-order truncation for negative: keep sign?
		// Simplify: mod then adjust
		v = v % mod
		if v < 0 {
			v += mod
		}
		// but sign handling not needed for this program
	} else {
		v = v % mod
	}
	fmtStr := fmt.Sprintf("%%0%dd", digits)
	return fmt.Sprintf(fmtStr, v)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func delimitedBySpace(s string) string {
	idx := strings.IndexByte(s, ' ')
	if idx == -1 {
		return s
	}
	return s[:idx]
}

func MAINPARA() {
	// OPEN INPUT PART-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// If file doesn't exist, treat as empty (COBOL would error, but we handle)
		// To match expected behaviour, exit with error to stderr
		if os.IsNotExist(err) {
			partFileLines = []string{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		scanner := bufio.NewScanner(f)
		// increase buffer for long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			// Scanner strips \n and \r, but if file had \r\n, \r is stripped? ScanLines strips \r.
			// Keep as is
			partFileLines = append(partFileLines, line)
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		f.Close()
	}
	partFileIndex = 0

	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE PART-FILE
	SUMMARYPARA()
}

func READPARA() {
	if partFileIndex >= len(partFileLines) {
		WsEofFlag = "Y"
		return
	}
	raw := partFileLines[partFileIndex]
	partFileIndex++

	// COBOL LINE SEQUENTIAL: one record per line, pad with spaces on right if shorter
	// Record length 15
	const recLen = 15
	if len(raw) < recLen {
		raw = raw + strings.Repeat(" ", recLen-len(raw))
	} else if len(raw) > recLen {
		raw = raw[:recLen]
	}
	// parse fields by offset
	lbPart := raw[0:8]
	lbRegion := raw[8:11]
	lbSerialStr := raw[11:15]

	var lbSerial int64 = 0
	// PIC 9(4) - digits only, implied. Parse as integer.
	// If string contains spaces (due to padding), treat spaces as zero? But parse numeric part.
	trim := strings.TrimSpace(lbSerialStr)
	if trim == "" {
		lbSerial = 0
	} else {
		// parse digits; if non-digit, treat as 0
		var v int64 = 0
		for _, ch := range lbSerialStr {
			if ch >= '0' && ch <= '9' {
				v = v*10 + int64(ch-'0')
			}
		}
		// However need to consider leading zeros: the above works.
		// For strict PIC, the 4 chars are digits; v is correct.
		lbSerial = v
		// If the field was e.g. "0012", v=12, formatting later will restore "0012".
	}

	PartRecGlobal.LbPart = lbPart
	PartRecGlobal.LbRegion = lbRegion
	PartRecGlobal.LbSerial = lbSerial
}

func PROCESSPARA() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	// count occurrences of "A" in LB-PART
	cnt := strings.Count(PartRecGlobal.LbPart, "A")
	WsACount = int64(cnt) % 100 // PIC 99 truncation
	// STRING ...
	// LB-REGION DELIMITED BY SPACE
	partRegion := delimitedBySpace(PartRecGlobal.LbRegion)
	partPart := delimitedBySpace(PartRecGlobal.LbPart)
	// LB-SERIAL DELIMITED BY SIZE -> 4 digits zero-padded
	serialStr := formatPic9(PartRecGlobal.LbSerial, 4)

	// Build concatenated string
	var sb strings.Builder
	sb.WriteString(partRegion)
	sb.WriteString("-")
	sb.WriteString(partPart)
	sb.WriteString("-")
	sb.WriteString(serialStr)
	concatenated := sb.String()

	// INTO WS-LABEL (20 chars), blanked first, truncate if overflow
	if len(concatenated) > 20 {
		concatenated = concatenated[:20]
	}
	// Place into WsLabel (which is 20 spaces)
	// STRING does not clear, pointer starts at 1, we already blanked
	WsLabel = concatenated + strings.Repeat(" ", 20-len(concatenated))

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A (PIC 999 low-order truncation)
	WsTotalA = (WsTotalA + WsACount) % 1000
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 1000

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is X(20) exactly, WS-A-COUNT is PIC 99 zero-padded 2 digits
	displayACount := formatPic9(WsACount, 2)
	// Concatenated exactly as COBOL DISPLAY
	fmt.Printf("%s A=%s\n", WsLabel, displayACount)

	READPARA()
}

func SUMMARYPARA() {
	// DISPLAY "LABELS: " WS-COUNT " A-TOTAL: " WS-TOTAL-A.
	countStr := formatPic9(WsCount, 3)
	totalStr := formatPic9(WsTotalA, 3)
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", countStr, totalStr)
}

func main() {
	MAINPARA()
}
